extends Node

const TRAINING_ROOM: StringName = &"training_room"
const DUO_CAPACITY: int = 2
const SQUAD_CAPACITY: int = 4
const COOP_PORT: int = 7017
const LOCAL_ADDRESS: String = "127.0.0.1"

@export var training_room: PackedScene
@export var player_scene: PackedScene
@export var menu: Control
@export var squad_mode: CheckButton
@export var host_button: Button
@export var join_button: Button
@export var status: Label

var _game: GameRuntime


func _ready() -> void:
    host_button.pressed.connect(_open_session.bind(true))
    join_button.pressed.connect(_open_session.bind(false))
    if training_room == null or player_scene == null:
        status.text = "Assign the training room and player scenes."
        _set_menu_busy(true)


func _open_session(hosting: bool) -> void:
    if _game != null:
        return

    _set_menu_busy(true)
    var capacity: int = SQUAD_CAPACITY if squad_mode.button_pressed else DUO_CAPACITY
    var rules: MultiplayerRules = MultiplayerRules.listen_coop()
    rules.max_players = capacity
    rules.port = COOP_PORT
    rules.join_in_progress = true

    var definition: GameDefinition = GameRuntime.configure()
    definition.starting_world = TRAINING_ROOM
    definition.starting_world_scene = training_room
    definition.player_scene = player_scene
    definition.multiplayer_rules = rules
    _game = definition.boot(self)
    if _game == null:
        status.text = "Could not create the game."
        _set_menu_busy(false)
        return

    var operation: GameOperation
    if hosting:
        status.text = "Opening a %d-player training room..." % capacity
        operation = _game.host_game(LOCAL_ADDRESS)
    else:
        status.text = "Joining the training room..."
        operation = _game.join_game(LOCAL_ADDRESS)

    var result: Dictionary = await operation.wait()
    if not result.ok:
        status.text = "Could not enter the training room: %s" % result.message
        _game.queue_free()
        await _game.tree_exited
        _game = null
        _set_menu_busy(false)
        return

    menu.hide()


func _set_menu_busy(busy: bool) -> void:
    host_button.disabled = busy
    join_button.disabled = busy
    squad_mode.disabled = busy

extends Node

const PRACTICE_ARENA: StringName = &"training_room"
const PRACTICE_CAPACITY: int = 4
const PRACTICE_PORT: int = 7017
const LOCAL_ADDRESS: String = "127.0.0.1"

@export var arena_scene: PackedScene
@export var player_scene: PackedScene
@export var host_practice: Button
@export var status: Label

var _game: GameRuntime


func _ready() -> void:
    host_practice.pressed.connect(_host_practice)


func _host_practice() -> void:
    if arena_scene == null or player_scene == null:
        status.text = "Assign the practice arena and player scenes."
        return

    host_practice.disabled = true
    status.text = "Opening the practice room..."
    var rules: MultiplayerRules = (
        MultiplayerRules.listen_coop()
        .with_max_players(PRACTICE_CAPACITY)
        .allow_join_in_progress(true)
        .on_port(PRACTICE_PORT)
    )
    var definition: GameDefinition = (
        GameRuntime.configure()
        .with_starting_world(PRACTICE_ARENA, arena_scene)
        .with_player(player_scene)
        .with_multiplayer(rules)
    )
    _game = definition.boot(self)
    if _game == null:
        status.text = "Could not create the practice room."
        host_practice.disabled = false
        return

    var result: Dictionary = await _game.host_game(LOCAL_ADDRESS).wait()
    if not result.ok:
        status.text = "Could not host: %s" % result.message
        _game.queue_free()
        await _game.tree_exited
        _game = null
        host_practice.disabled = false
        return

    host_practice.hide()
    status.text = "Practice is open to %d players, including you." % PRACTICE_CAPACITY

extends Control

const MENU_ACTION: StringName = &"ui_cancel"

@export var game: GameRuntime
@export var rules_label: Label
@export var resume_button: Button


func _ready() -> void:
    hide()
    resume_button.pressed.connect(hide)


func _unhandled_input(event: InputEvent) -> void:
    if not event.is_action_pressed(MENU_ACTION):
        return
    if not is_instance_valid(game) or game.get_local_player() == null:
        return

    get_viewport().set_input_as_handled()
    if visible:
        hide()
        return

    var definition: GameDefinition = game.get_definition()
    var rules: MultiplayerRules = definition.get_multiplayer_rules()
    if rules == null:
        rules_label.text = "Solo session"
    else:
        var drop_in: String = "Open" if rules.get_join_in_progress() else "Closed"
        rules_label.text = "Co-op capacity: %d\nUDP port: %d\nDrop-in: %s" % [
            rules.get_max_players(), rules.get_port(), drop_in
        ]

    show()
    resume_button.grab_focus()

extends Node

const SPAWN_POINTS: NodePath = ^"SpawnPoints"
const PLAYER_CAMERA: NodePath = ^"Camera3D"
const PLAYER_BODY: NodePath = ^"Body"

@export var practice_range: PackedScene
@export var player_scene: PackedScene
@export var start_practice: Button
@export var exit_range: Button
@export var status: Label

var _session: WorldSession


func _ready() -> void:
    exit_range.hide()
    start_practice.pressed.connect(_enter_range)
    exit_range.pressed.connect(_exit_range)
    if practice_range == null or player_scene == null:
        status.text = "Assign the practice range and player scenes."
        start_practice.disabled = true
        return

    var definition: WorldSessionDefinition = (
        WorldSession.configure()
        .with_world(practice_range)
        .with_players(player_scene, SPAWN_POINTS)
        .with_local_view(PLAYER_CAMERA, PLAYER_BODY)
    )
    _session = definition.create()
    add_child(_session)
    _session.session_ended.connect(_on_session_ended)


func _enter_range() -> void:
    var error: Error = _session.start_offline()
    if error != OK:
        status.text = "Could not open the practice range: %s" % error_string(error)
        return

    var player: Node3D = _session.get_local_player()
    var position: Vector3 = player.global_position
    status.text = "Practice range | Starting position: %s" % position
    start_practice.hide()
    exit_range.show()


func _exit_range() -> void:
    var error: Error = _session.leave()
    if error != OK:
        status.text = "Could not exit the practice range: %s" % error_string(error)


func _on_session_ended(_reason: StringName) -> void:
    exit_range.hide()
    start_practice.show()
    status.text = "Choose Start Practice to return to the range."

extends Node

const TRAINING_ROOM: StringName = &"training_room"
const FIRST_PERSON_CAMERA: NodePath = ^"Eyes"
const CHASE_CAMERA: NodePath = ^"ChaseCamera"
const BODY: NodePath = ^"Body"
const LOCAL_VIEW: NodePath = ^"LocalPlayerView"

@export var room_scene: PackedScene
@export var player_template: PackedScene
@export var menu: Control
@export var first_person_mode: CheckButton
@export var play_button: Button
@export var status: Label


func _ready() -> void:
    play_button.pressed.connect(_play)


func _play() -> void:
    if room_scene == null or player_template == null:
        status.text = "Assign the training room and the player template."
        return

    var player_scene: PackedScene = _make_player_scene(first_person_mode.button_pressed)
    if player_scene == null:
        return

    play_button.disabled = true
    var definition: GameDefinition = (
        GameRuntime.configure()
        .with_starting_world(TRAINING_ROOM, room_scene)
        .with_player(player_scene)
    )
    var game: GameRuntime = definition.boot(self)
    if game == null:
        status.text = "Could not create the game."
        play_button.disabled = false
        return

    var result: Dictionary = await game.play_solo().wait()
    if not result.ok:
        status.text = "Could not enter the training room: %s" % result.message
        game.queue_free()
        await game.tree_exited
        play_button.disabled = false
        return

    menu.hide()


func _make_player_scene(first_person: bool) -> PackedScene:
    var actor: Node = player_template.instantiate()
    if actor == null:
        status.text = "Could not instantiate the player template."
        return null

    var camera_path: NodePath = FIRST_PERSON_CAMERA if first_person else CHASE_CAMERA
    var camera: Camera3D = actor.get_node_or_null(camera_path) as Camera3D
    var body: Node3D = actor.get_node_or_null(BODY) as Node3D
    var view: LocalPlayerView = actor.get_node_or_null(LOCAL_VIEW) as LocalPlayerView
    if actor is not Node3D or camera == null or body == null or view == null:
        status.text = "The player template needs both cameras, a body, and a LocalPlayerView."
        actor.free()
        return null

    view.camera = camera
    view.hidden_visuals = body if first_person else null

    # Save the view references in the scene that Crimson will spawn.
    var player_scene: PackedScene = PackedScene.new()
    var error: Error = player_scene.pack(actor)
    actor.free()
    if error != OK:
        status.text = "Could not prepare the player scene: %s" % error_string(error)
        return null
    return player_scene
